from sys import stdin, stdout

def main():
    x = int(stdin.readline().strip())
    hh, mm = map(int, stdin.readline().strip().split(':'))

    target_minutes = hh * 60 + mm

    def has_lucky_digit(time):
        return '7' in str(time)

    current_time = target_minutes
    snooze_count = 0

    while True:
        if has_lucky_digit(current_time):
            break
        current_time -= x
        snooze_count += 1

        # Handle wrap-around for hours
        if current_time < 0:
            current_time += 24 * 60

    stdout.write(str(snooze_count) + '\n')

if __name__ == "__main__":
    main()
